def run(cmd,cwd=None,env=None,check=True,capture=False):
    print("+"," ".join(map(str,cmd)),flush=True)
    return subprocess.run(
        list(map(str,cmd)),cwd=cwd,env=env,check=check,text=True,
        capture_output=capture,
    )

def setup_conda():
    conda=MINICONDA/"bin/conda"
    if conda.exists():
        return conda
    installer=TMP/"miniforge.sh"
    urllib.request.urlretrieve(
        "https://github.com/conda-forge/miniforge/releases/latest/download/Miniforge3-Linux-x86_64.sh",
        installer,
    )
    run(["bash",str(installer),"-b","-p",str(MINICONDA)])
    return conda

def locate_driver_dirs():
    candidates=[]
    for raw in os.environ.get("LD_LIBRARY_PATH","").split(":"):
        if not raw:
            continue
        p=Path(raw)
        if p.exists() and any((p/n).exists() for n in ("libcuda.so.1","libcuda.so")):
            candidates.append(str(p))
    probe=subprocess.run(
        ["bash","-lc",
         "ldconfig -p 2>/dev/null | "
         "grep -E 'libcuda\\.so\\.1|libnvidia-ptxjitcompiler\\.so\\.1|libnvidia-nvvm\\.so' || true"],
        capture_output=True,text=True,check=False,
    )
    print("Driver probe:\n"+probe.stdout,flush=True)
    for line in probe.stdout.splitlines():
        if "=>" in line:
            p=Path(line.split("=>",1)[1].strip()).parent
            if p.exists():
                candidates.append(str(p))
    for fallback in ("/usr/local/nvidia/lib64","/usr/local/nvidia/lib","/usr/lib/x86_64-linux-gnu"):
        p=Path(fallback)
        if p.exists() and any((p/n).exists() for n in ("libcuda.so.1","libcuda.so")):
            candidates.append(str(p))
    out=[]
    for p in candidates:
        if p not in out:
            out.append(p)
    if not out:
        raise RuntimeError("Could not locate Kaggle NVIDIA driver libraries")
    return out,probe.stdout

def setup_odin(conda):
    env=os.environ.copy()
    env["PATH"]=f"{MINICONDA}/bin:"+env.get("PATH","")
    env.pop("PYTHONPATH", None)
    env.pop("PYTHONHOME", None)
    if not ODIN.exists():
        run([
            "git","clone","--recurse-submodules","--depth","1",
            "https://github.com/DigBioLab/odin_multi.git",str(ODIN)
        ],env=env)
    marker=MINICONDA/"envs/Odin-Multi/bin/python"
    channels = run(
        [str(MINICONDA/"bin/conda"), "config", "--show", "channels"],
        env=env, capture=True, check=False,
    )
    (OUT/"conda_channels.txt").write_text(
        (channels.stdout or "") + (channels.stderr or ""),
        encoding="utf-8",
    )
    print("Conda channels:\n" + (channels.stdout or ""), flush=True)
    if not marker.exists():
        run([
            "bash","install_odin_multi.sh",
            "--cuda","12.4",
            "--pkg-manager","conda",
        ],cwd=ODIN,env=env)
    else:
        print("Odin-Multi conda environment already present.",flush=True)
    return env

EXPECTED_TARGET_RESIDUES={
    "human_tfr1_apical_189_383.pdb":(189,383,195),
    "mouse_tfr1_apical_homolog.pdb":(191,385,194),
}


def _ca_residues(path):
    nums=[]
    for line in path.read_text(errors="replace").splitlines():
        if line.startswith("ATOM") and len(line)>=54 and line[12:16].strip()=="CA":
            try:
                nums.append(int(line[22:26]))
            except ValueError:
                continue
    return nums


def _ca_residues_by_chain(path):
    out={}
    for line in path.read_text(errors="replace").splitlines():
        if line.startswith("ATOM") and len(line)>=54 and line[12:16].strip()=="CA":
            chain=line[21].strip() or "_"
            try:
                resid=int(line[22:26])
            except ValueError:
                continue
            out.setdefault(chain,[]).append(resid)
    return out


def materialize_targets():
    """Write the embedded target PDBs to disk and fail fast if anything is wrong.

    This MUST run before the ~12 minute conda/Odin-Multi installation so that a
    packaging regression costs seconds instead of a whole GPU session. The
    2026-10-29 smoke failed only after the full install because the inputs were
    never uploaded by `kaggle kernels push` (script kernels ship `code_file` only).
    """
    print("=== Stage 0: verifying embedded target inputs ===",flush=True)
    missing=[n for n in EXPECTED_TARGET_RESIDUES if n not in EMBEDDED_TARGET_GZ_B64]
    if missing:
        raise SystemExit(
            "FATAL: embedded target payload missing for "+", ".join(sorted(missing))
            +". Run `python scripts/embed_odin_multi_targets.py` and re-push."
        )

    paths={}
    for name,(lo,hi,expected_ca) in EXPECTED_TARGET_RESIDUES.items():
        dest=OUT/name
        try:
            raw=gzip.decompress(base64.b64decode(EMBEDDED_TARGET_GZ_B64[name]))
        except Exception as exc:
            raise SystemExit(f"FATAL: cannot decode embedded payload for {name}: {exc}")

        digest=hashlib.sha256(raw).hexdigest()
        expected=EMBEDDED_TARGET_SHA256.get(name)
        if digest!=expected:
            raise SystemExit(
                f"FATAL: sha256 mismatch for {name}: got {digest}, expected {expected}. "
                "The embedded payload is out of sync with the repository PDB."
            )

        dest.write_bytes(raw)
        nums=_ca_residues(dest)
        if not nums:
            raise SystemExit(f"FATAL: no CA atoms parsed from {name}.")
        if min(nums)!=lo or max(nums)!=hi or len(nums)!=expected_ca:
            raise SystemExit(
                f"FATAL: {name} residue numbering is wrong: CA range "
                f"{min(nums)}-{max(nums)} count {len(nums)}, expected {lo}-{hi} count {expected_ca}. "
                "Hotspot restraints would silently miss their intended residues."
            )
        print(
            f"  OK {name}: {len(raw)} bytes, sha256={digest[:16]}..., "
            f"CA {min(nums)}-{max(nums)} (n={len(nums)}) -> {dest}",
            flush=True,
        )
        paths[name]=dest

    # The mouse model is the human apical frame renumbered +2; the hotspot pairs
    # must line up or the cross-reactivity objective is meaningless.
    human_ca=set(_ca_residues(paths["human_tfr1_apical_189_383.pdb"]))
    mouse_ca=set(_ca_residues(paths["mouse_tfr1_apical_homolog.pdb"]))
    for h,m in ((343,345),(344,346),(347,349),(350,352)):
        if h not in human_ca:
            raise SystemExit(f"FATAL: human hotspot {h} absent from target PDB.")
        if m not in mouse_ca:
            raise SystemExit(f"FATAL: mouse hotspot {m} absent from target PDB.")
    print("  OK all 4 human/mouse hotspot pairs present.",flush=True)

    for name,spec in ESCAPE_SPECS.items():
        if name not in EMBEDDED_ESCAPE_B64:
            raise SystemExit(f"FATAL: missing embedded escape decoy {name}")
        dest=OUT/name
        raw=base64.b64decode(EMBEDDED_ESCAPE_B64[name])
        dest.write_bytes(raw)
        by_chain=_ca_residues_by_chain(dest)
        for chain,(lo,hi,n) in spec.items():
            vals=by_chain.get(chain,[])
            if not vals or min(vals)!=lo or max(vals)!=hi or len(vals)!=n:
                raise SystemExit(
                    f"FATAL: {name} chain {chain} CA range/count wrong: "
                    f"{(min(vals),max(vals),len(vals)) if vals else 'missing'}, "
                    f"expected {(lo,hi,n)}"
                )
        print(
            f"  OK {name}: "
            +", ".join(
                f"{ch} {min(by_chain[ch])}-{max(by_chain[ch])} (n={len(by_chain[ch])})"
                for ch in sorted(spec)
            ),
            flush=True,
        )
        paths[name]=dest

    print("=== Stage 0 passed ===",flush=True)
    return paths



V6_WARM_START_SEQUENCE="SPSVISTTTTTYTYHGKQVTRIRTTINPGEKIEPAPGERQMRGRDWETGYIIVHTYKVNS"

def patch_odin_warm_start():
    """Warm-start the shared multi-context sequence from the validated v6 parent.

    Odin/ColabDesign evaluates auxiliary target contexts with the same params["seq"],
    so restarting the main design model with this sequence initializes every target
    context from one shared binder sequence. The patch is deliberately inserted only
    after all target contexts have been prepared and before campaign loss weights are set.
    """
    path=ODIN/"functions/colabdesign_utils.py"
    text=path.read_text()
    old='''    if aux_params_list:
        af_model.prep_offtarget_inputs(aux_params_list)

    af_model._args["gradient_weight"] = float(main_advanced["gradient_weight"])
'''
    new=f'''    if aux_params_list:
        af_model.prep_offtarget_inputs(aux_params_list)

    v6_seq = "SPSVISTTTTTYTYHGKQVTRIRTTINPGEKIEPAPGERQMRGRDWETGYIIVHTYKVNS"
    f39_seq = "SPSVISTTTETYTPHGKQVTRIRTTINPGEKIEPAPGERQMPGRDADTGYTVVHTYKVNS"
    warm_start_seq = f39_seq if int(seed) == 807250 else v6_seq
    warm_label = "F39_mouse_apical" if int(seed) == 807250 else "v6_human_parent"
    if len(warm_start_seq) != length:
        raise ValueError(f"Warm-start length {{len(warm_start_seq)}} != requested binder length {{length}}")
    print(f"[WARM START] {{warm_label}}: shared binder ({{length}} aa), design seed={{seed}}")
    af_model.restart(seed=seed, seq=warm_start_seq)

    af_model._args["gradient_weight"] = float(main_advanced["gradient_weight"])
'''
    if old not in text:
        raise RuntimeError("Odin warm-start insertion point not found; refusing unverified patch")
    path.write_text(text.replace(old,new,1))
    (OUT/"odin_warm_start_patch.txt").write_text(
        "Inserted af_model.restart(seed=seed, seq=V6_WARM_START_SEQUENCE) after multi-context prep.\n"
        "Shared sequence: "+V6_WARM_START_SEQUENCE+"\n"
    )
    print("Patched Odin-Multi for shared v6 sequence warm-start.",flush=True)


def prepare_inputs():
    human=OUT/"human_tfr1_apical_189_383.pdb"
    mouse=OUT/"mouse_tfr1_apical_homolog.pdb"
    decoys={
        "human_escape_606_678":OUT/"human_escape_606_678.pdb",
        "human_escape_145_187":OUT/"human_escape_145_187.pdb",
        "mouse_escape_516_582":OUT/"mouse_escape_516_582.pdb",
        "mouse_escape_629_680":OUT/"mouse_escape_629_680.pdb",
    }
    for pdb in (human,mouse,*decoys.values()):
        if not pdb.exists(): raise SystemExit(f"FATAL: missing {pdb}")

    human_json={"binder_name":"human_tfr1_apical","starting_pdb":str(human),"chains":"A","target_hotspot_residues":"A347,A350"}
    mouse_json={"binder_name":"mouse_tfr1_apical","starting_pdb":str(mouse),"chains":"A","target_hotspot_residues":"A349,A352"}

    human_loss={
        "role":"target","gradient_weight":1.0,"rm_template_seq_design":False,"rm_template_sc_design":False,
        "weights_plddt":0.1,"weights_pae_intra":0.35,"weights_pae_inter":0.15,
        "weights_con_intra":0.9,"weights_con_inter":1.5,"intra_contact_distance":14.0,"inter_contact_distance":8.0,
        "intra_contact_number":2,"inter_contact_number":1,"intra_contact_num_pos":1000,"inter_contact_num_pos":1000,
        "weights_helicity":-0.3,"use_i_ptm_loss":True,"weights_iptm":0.15,
        "use_ptm_energy_craft_loss":False,"weights_ptm_energy_craft":0.0,"weights_rg":0.25,"use_rg_loss":True,
        "weights_termini_loss":0.1,"use_termini_distance_loss":False,"mpnn_backprop_num_samples":4,
        "weights_mpnn_structure_confidence":0.0,"weights_mpnn_sequence_kl":0.0,
        "weights_mpnn_autoregressive_ce":0.5,"mpnn_interface_only":False
    }
    mouse_loss=dict(human_loss); mouse_loss["gradient_weight"]=1.25

    def off(weight):
        return {
            "role":"offtarget","gradient_weight":weight,"rm_template_seq_design":False,"rm_template_sc_design":False,
            "weights_plddt":0.0,"weights_pae_intra":0.0,"weights_pae_inter":-0.15,
            "weights_con_intra":0.0,"weights_con_inter":-1.25,"intra_contact_distance":14.0,"inter_contact_distance":8.0,
            "intra_contact_number":2,"inter_contact_number":1,"weights_contact_max":0.0,"weights_helicity":0.0,
            "use_i_ptm_loss":True,"weights_iptm":-0.08,"use_ptm_energy_craft_loss":False,"weights_ptm_energy_craft":0.0,
            "clip":{"i_pae":{"below":0.35},"i_con":{"below":3.5},"i_ptm":{"above":0.30}},
            "weights_rg":0.0,"use_rg_loss":False,"weights_termini_loss":0.0,"use_termini_distance_loss":False,
            "mpnn_backprop_num_samples":4,"weights_mpnn_structure_confidence":0.0,"weights_mpnn_sequence_kl":0.0,
            "weights_mpnn_autoregressive_ce":-0.5,"mpnn_interface_only":True
        }
    weights={"human_escape_606_678":0.55,"human_escape_145_187":0.25,"mouse_escape_516_582":0.45,"mouse_escape_629_680":0.45}
    general={
        "lengths":[60,60],"use_multimer_design":True,"af_params_dir":"","num_recycles_design":1,"sample_models":True,
        "ensemble_discrete_stages":False,"design_algorithm":"3stage_ste","soft_iterations":45,"temporary_iterations":15,
        "hard_iterations":10,"greedy_iterations":5,"greedy_percentage":5,"use_early_stopping":False,"optimise_beta":True,
        "optimise_beta_extra_soft":0,"optimise_beta_extra_temp":0,"optimise_beta_recycles_design":3,
        "mpnn_weights":"original","mpnn_use_ligand_context":False,"random_helicity":False,
        "save_design_animations":False,"save_design_trajectory_plots":False,"remove_unrelaxed_trajectory":False,"omit_AAs":"C"
    }
    objs=[("human_target.json",human_json),("mouse_target.json",mouse_json),("human_loss.json",human_loss),("mouse_loss.json",mouse_loss),("general_hard_negative_v5.json",general)]
    for name,path in decoys.items():
        objs.append((name+"_target.json",{"binder_name":name,"starting_pdb":str(path),"chains":"A","target_hotspot_residues":None}))
        objs.append((name+"_loss.json",off(weights[name])))
    paths={}
    for name,obj in objs:
        p=OUT/name; p.write_text(json.dumps(obj,indent=2)+"\n"); paths[name]=p
    return paths

def main():
    t0=time.time()
    run(["nvidia-smi"],check=False)
    print("Host Python",sys.version,flush=True)

    # Fail fast on packaging problems BEFORE the ~12 minute environment install.
    materialize_targets()

    conda=setup_conda()
    env=setup_odin(conda)
    patch_odin_warm_start()

    driver_dirs,probe=locate_driver_dirs()
    env["LD_LIBRARY_PATH"]=":".join(driver_dirs + [x for x in env.get("LD_LIBRARY_PATH","").split(":") if x])
    env["CUDA_VISIBLE_DEVICES"]="0"
    (OUT/"driver_probe.txt").write_text(
        "selected_driver_dirs="+":".join(driver_dirs)+"\n"+probe
    )

    # Verify actual JAX GPU visibility rather than relying on nvidia-smi inside conda.
    run([
        str(conda),"run","--no-capture-output","-n","Odin-Multi",
        "python","-c",
        "import jax; print('JAX devices:',jax.devices()); "
        "assert any(d.platform=='gpu' for d in jax.devices()), 'No JAX GPU'"
    ],cwd=ODIN,env=env)

    paths=prepare_inputs()
    rundir=OUT/"run"

    design_cmd=[
        str(conda),"run","--no-capture-output","-n","Odin-Multi",
        "python","-u",str(ODIN/"odin_multi.py"),"design",
        "--run-dir",str(rundir),
        "--context",str(paths["human_target.json"]),str(paths["human_loss.json"]),
        "--context",str(paths["mouse_target.json"]),str(paths["mouse_loss.json"]),
        "--context",str(paths["human_escape_606_678_target.json"]),str(paths["human_escape_606_678_loss.json"]),
        "--context",str(paths["human_escape_145_187_target.json"]),str(paths["human_escape_145_187_loss.json"]),
        "--context",str(paths["mouse_escape_516_582_target.json"]),str(paths["mouse_escape_516_582_loss.json"]),
        "--context",str(paths["mouse_escape_629_680_target.json"]),str(paths["mouse_escape_629_680_loss.json"]),
        "--advanced",str(paths["general_hard_negative_v5.json"]),
        "--base-seed","20261108",
        "--num-designs","2",
    ]
    proc=run(design_cmd,cwd=ODIN,env=env,check=False)
    (OUT/"design_exit_code.txt").write_text(str(proc.returncode)+"\n")
    if proc.returncode!=0:
        raise SystemExit(proc.returncode)

    select_cmd=[
        str(conda),"run","--no-capture-output","-n","Odin-Multi",
        "python","-u",str(ODIN/"odin_multi.py"),"select",
        "--run-dir",str(rundir),
        "--method","best_clipped_i_pae_ratio",
    ]
    sel=run(select_cmd,cwd=ODIN,env=env,check=False)
    (OUT/"select_exit_code.txt").write_text(str(sel.returncode)+"\n")
    if sel.returncode!=0:
        raise SystemExit(sel.returncode)

    selection=rundir/"02_selections/best_clipped_i_pae_ratio/selection.csv"
    fasta=rundir/"02_selections/best_clipped_i_pae_ratio/sequences.fasta"
    summary={
        "contexts":[
            {"name":"human_tfr1_apical","role":"target","hotspots":[347,350],"gradient_weight":1.0},
            {"name":"mouse_tfr1_apical","role":"target","hotspots":[349,352],"gradient_weight":1.25},
            {"name":"human_escape_decoys","role":"offtarget","regions":["122-188","500-760"],"gradient_weight":0.20},
            {"name":"mouse_escape_decoys","role":"offtarget","regions":["123-188","500-763"],"gradient_weight":0.20},
        ],
        "binder_length":60,
        "trajectory_count":2,
        "selection_method":"best_clipped_i_pae_ratio",
        "warm_start":"t0=v6; t1=F39",
        "design_iterations":{"soft":45,"temporary":15,"hard":10,"greedy":5},
        "selection_csv_exists":selection.exists(),
        "selection_fasta_exists":fasta.exists(),
        "elapsed_min":round((time.time()-t0)/60,1),
    }
    if selection.exists():
        shutil.copy2(selection,OUT/"selection.csv")
    if fasta.exists():
        shutil.copy2(fasta,OUT/"selected_sequences.fasta")
    (OUT/"smoke_summary.json").write_text(json.dumps(summary,indent=2)+"\n")
    print(json.dumps(summary,indent=2),flush=True)

    shutil.make_archive(
        str(WORK/"tfr1_odin_multi_hard_negative_v5"),
        "zip",
        root_dir=OUT,
    )

if __name__=="__main__":
    main()
